# -*- coding: utf-8 -*-
"""ch03 R3 ops 7: 3.4区+术语速查 (对R2后行号)"""

OPS = [
(393, 393, "* **超高适用条件与定义**",
 "* **超高适用条件与定义**：依《深圳建筑工程消耗量定额2024》与《房屋建筑与装饰工程消耗量定额》，建筑物超高增加费指高层建筑施工中，施工人员垂直交通与休息时间延长造成的人工降效、配合机械随之产生的降效，以及高层水压不足发生的加压水泵台班费用（P000302、P000303）。适用于高度8层或24米以上的工程，费用直接列入分部分项工程或相应措施项目的综合单价（P000303）。"),
(394, 394, "* **建筑物高度确定标准**",
 "* **建筑物高度确定标准**：高度指设计室外地坪标高至屋顶结构层上表面标高；突出屋面的楼梯间、设备房等水平投影面积大于屋顶水平投影面积三分之一时，高度计至其顶板结构层上表面标高；室外地坪标高不等时按平均标高算（P000303）。"),
(404, 404, "* **边生产边施工干扰降效调整**",
 "* **边生产边施工干扰降效调整**：施工与生产同时进行使施工受干扰，或在有害身体健康（按有关部门规定）环境下施工造成的降效，按相应定额子目**人工费乘系数1.10**执行；有专项施工方案的，按经审定的方案另行计算（P000303）。"),
(405, 405, "* **材料二次运输费加算条件**",
 "* **材料二次运输费加算条件**：定额子目消耗量已综合包含材料、成品、半成品自工地仓库或集中堆放点至操作地点的场内水平与垂直运输损耗及人工机械消耗（P000302、P000303）；但施工环境或场地条件受限（老城区狭窄场地、临街建筑无堆场）致材料不能直接运至堆放点、需转运而重复装卸运输的，**应另行计算二次运输费**（P000303）。"),
(408, 408, "* **普通公路养护工程的干扰与降效特性**",
 "* **普通公路养护工程的干扰与降效特性**：依《2021四川省国省干线普通公路养护预算定额》及《公路工程预算定额释义手册》，普通公路养护工程（路基修复、危石处理、清淤回填、清理坍方等）具有“边通车边施工、作业面分散、单次工程量小”的特点（P000310、P000316）；养护定额编制时已综合考虑行车干扰下人员机械频繁避让的降效（P000310、P000316），路基工程中人工挖运土方、机动翻斗车配合运土石方等子目的工效指标均已按养护实际降效调整，消耗量高于新建公路（P000305、P000310、P000316）。"),
(409, 409, "* **定额换算（H）与补充定额编制实战要领**",
 "* **定额换算（H）与补充定额编制实战要领**：分项工程设计要求、材料规格或施工方法与定额取定不符且规则允许调整时，须按总说明与分部说明在子目编号尾部注“换”或“H”换算套用（流程详见3.4.2节）（P000319）；定额完全缺项的新技术、新工艺或特殊场地条件（如四川土地开发整理项目的特殊地形施工），按定额编制原则编**补充定额**，随预算文件送审或报管理部门备案（P000302、P000305、P000309）。"),
(414, 414, "* **案情**：某施工单位承接一幢",
 "* **案情**：某施工单位承接繁华商业区一幢高层商业综合体，塔楼施工期间发包方因商业安排令裙楼提前装修试营业，施工单位在裙楼续建区域继续施工；又因临街无堆场，材料须在场外租赁仓库落地后二次转运进场（P000303）。收尾结算时，双方对三项增加费用发生严重争议："),
(415, 417, "  1. **超高增加费**",
 "  1. **超高增加费**：施工单位按最高楼层降效系数对全部超高楼层人工费与机械费统一乘系数申报，审计单位主张按加权平均降效系数计算、拒绝全额支付（P000303）。\n  2. **施工干扰降效费**：施工单位主张裙楼试营业属“施工与生产同时进行”，要求整幢建筑物分部分项人工费统一乘1.10系数；发包方认为塔楼未受营业干扰，拒绝乘系数（P000303）。\n  3. **二次运输费**：施工单位按场外仓库转运实际发生额申报二次转运费，发包方以“定额子目已含场内水平与垂直运输”为由拒付（P000303）。"),
(447, 447, "当设计采用的混凝土强度等级",
 "设计混凝土强度等级（如 C30 改 C35）、砂浆强度等级（如 M5.0 改 M10.0）或水泥强度等级与定额取定不符时，按定额附录配合比表换算（P000305、P000319）。"),
(448, 448, "* **换算规则与红线**",
 "* **换算规则与红线**：原定额中砂浆或混凝土半成品消耗量（如 1.015m³ 或 1.02m³）保持不变，按附录配合比调换水泥、砂、石等原材料用量（P000305）。"),
(449, 449, "* **公路工程红线**",
 "* **公路工程红线**：依《公路工程预算定额》（JTG/T 3832—2018）总说明，定额内混凝土与砂浆配合比的水泥用量已综合考虑不同水泥品种因素，实际施工不论用何种水泥，**均不得调整定额水泥用量**；实际施工配合比与定额配合比表用量不同时，除表说明明确允许者外，**一律不得按实际施工配合比换算**（P000305）。"),
(452, 452, "在公路工程中，就地浇筑钢筋混凝土梁",
 "公路工程中就地浇筑钢筋混凝土梁的支架、拱圈的拱盔与支架，定额已综合考虑正常周转次数（P000305）；确因施工安排或特殊结构限制达不到规定周转次数的，可据实换算并按规定计算残值回收，其他周转材料一般不予抽换（P000305）。"),
(455, 455, "依据《房屋建筑与装饰工程消耗量定额》，定额装饰项目",
 "依《房屋建筑与装饰工程消耗量定额》，装饰项目中以木质饰面板、装饰线条表示的材质，通常按榉木、橡木等常用木种取定（P000302）；设计要求柚木、核桃木、水曲柳等其他材质的，按设计材质与定额取定材质的预算单价等量换算，人工费与机械费不调（P000302）。"),
(477, 477, "  1. **混凝土配合比超量索赔**",
 "  1. **混凝土配合比超量索赔**：现浇箱梁 C50 混凝土施工中，施工单位提出现场试验室的实际大体积配合比每立方米水泥用量比定额配合比表多 35kg，遂在定额换算时擅自按实际配合比增加水泥消耗量，申报增加材料费 42 万元。"),
(478, 478, "  2. **新工艺补充定额结算**",
 "  2. **新工艺补充定额结算**：桥面铺装采用的新型高分子防水涂层工艺（国家与地方公路定额均缺项），施工单位自行按内部实测成本编制补充定额（单价 180 元/㎡）直接计入结算总价，未向省级公路造价管理部门备案，也未上传“公路工程造价依据信息管理平台”（P000305）。"),
(530, 541, "* **预算定额**",
 "* **预算定额**：正常施工条件下完成一定计量单位合格分项工程或结构构件所需人工、材料、施工机械台班数量标准及其货币表现，传统“量价合一”计价体系核心依据 （P000312、P000320）。\n* **消耗量定额**：只界定合格分项工程所需人工工日、材料净用量及合理损耗、机械台班等物理“量”，不固化价格与管理费费率，是“量价分离”与企业自主定价的基础 （P000304）。\n* **人工幅度差**：合理施工组织下工种交接、工艺间歇、质量检查等无法按工序计入的工日损失，施工定额工效向预算定额工效转换的调整系数 （P000302、P000311）。\n* **机械幅度差**：机械正常施工中因场地转移、临时供电间歇、配合辅助机械等不可避免停歇降效增加的时间消耗 （P000302、P000315）。\n* **材料损耗率**：场内运输、操作、堆放不可避免损耗占净用量的百分比，\\\\(\\text{损耗率} = \\frac{\\text{损耗量}}{\\text{净用量}} \\times 100\\%\\\\) （P000302、P000303）。\n* **单位估价表**：定额工料机消耗量乘地区现行人工日工资单价、材料预算价格、机械台班单价算出的分项直接费基价汇总表 （P000311）。\n* **加权平均超高降效系数（\\\\(J_{\\text{平均}}\\\\)）**：高度超8层或24米时按各楼层建筑面积与对应区段降效系数加权的整栋调整系数 （P000303）。\n* **换算定额（H）**：设计规格、强度等级或工法与定额取定不符且规则允许换算时调整原定额要素形成的子目，编号尾注“换”或“H” （P000319）。\n* **补充定额**：“四新”致定额完全缺项时经现场实测与技术经济分析编制的临时计价依据，须依法备案并上传官方数据监管平台 （P000305、P000315）。\n* **秒表测时法**：现场对作业要素周期性观测、秒表记录时间消耗的方法，GB/T 23859—2025 两种现场测定法之一 （P000354）。\n* **影像记录法**：GB/T 23859—2025 新增测时方法，以可重现影像读取定时点时间，须事先取得作业人员同意 （P000354）。\n* **企业定额**：建筑企业按自身技术与管理水平编制、反映个别成本的内部定额，水平高于预算定额、低于施工定额，用于投标报价与成本控制 （P000321）。"),
]
